import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"MCP ツール","description":"","frontmatter":{},"headers":[],"relativePath":"ja/mcp-tools/overview.md","filePath":"ja/mcp-tools/overview.md","lastUpdated":1784903584000}'),a={name:"ja/mcp-tools/overview.md"};function n(r,t,s,i,l,p){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="mcp-ツール" tabindex="-1">MCP ツール <a class="header-anchor" href="#mcp-ツール" aria-label="Permalink to &quot;MCP ツール&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><p>swag2mcp は <strong>19 の MCP ツール</strong> を提供し、LLM エージェントが Model Context Protocol を通じて API に完全にアクセスできるようにします。これらのツールは、利用可能な API の発見、スペック階層のナビゲーション、エンドポイントの検索と検査、API 呼び出しの実行、大規模レスポンスの処理まで、完全なワークフローをカバーします。</p><h3 id="ツールが解決する課題" tabindex="-1">ツールが解決する課題 <a class="header-anchor" href="#ツールが解決する課題" aria-label="Permalink to &quot;ツールが解決する課題&quot;">​</a></h3><ul><li><strong>発見</strong> — LLM は ID を事前に知らなくてもスペック、コレクション、タグを見つけられます</li><li><strong>ナビゲーション</strong> — スペック → コレクション → タグ → エンドポイントの構造化された階層を掘り下げます</li><li><strong>検索</strong> — ID がない場合に全エンドポイントを全文検索</li><li><strong>検査</strong> — 呼び出し前に完全な OpenAPI 操作オブジェクトを取得</li><li><strong>実行</strong> — 自動認証付きで実際の API 呼び出しを実行</li><li><strong>大規模レスポンス処理</strong> — インラインに収まらない大きなレスポンスの概要表示、圧縮、スライス</li></ul><h3 id="読み取り専用-vs-可変" tabindex="-1">読み取り専用 vs 可変 <a class="header-anchor" href="#読み取り専用-vs-可変" aria-label="Permalink to &quot;読み取り専用 vs 可変&quot;">​</a></h3><table tabindex="0"><thead><tr><th>タイプ</th><th>数</th><th>ツール</th></tr></thead><tbody><tr><td><strong>読み取り専用</strong></td><td>17</td><td>すべての発見、エンドポイント、検索、検査、情報、レスポンスツール</td></tr><tr><td><strong>可変</strong></td><td>2</td><td><code>invoke</code>（実際の HTTP 呼び出し）、<code>auth</code>（トークン取得）</td></tr></tbody></table><p>読み取り専用ツールは MCP プロトコルで <code>ReadOnlyHint=true</code> および <code>IdempotentHint=true</code> とマークされ、LLM に副作用なく安全に呼び出せることを示します。</p><h3 id="エラーハンドリング" tabindex="-1">エラーハンドリング <a class="header-anchor" href="#エラーハンドリング" aria-label="Permalink to &quot;エラーハンドリング&quot;">​</a></h3><p>すべてのツールは、機械可読なコードと人間可読なメッセージを含む構造化された <code>LLMError</code> オブジェクトとしてエラーを返します：</p><table tabindex="0"><thead><tr><th>エラーコード</th><th>意味</th></tr></thead><tbody><tr><td><code>validation_failed</code></td><td>無効な入力（不正な ID 形式、必須フィールドの欠落）</td></tr><tr><td><code>not_found</code></td><td>インデックスまたはワークスペースにエンティティが見つからない</td></tr><tr><td><code>rate_limit</code></td><td>同じエンドポイントへの 10 秒以内の 2 回目の <code>invoke</code> 呼び出し</td></tr><tr><td><code>invoke_error</code></td><td>HTTP 呼び出しの失敗、ダウンロードの失敗</td></tr><tr><td><code>auth_error</code></td><td>認証トークン取得の失敗</td></tr><tr><td><code>config_error</code></td><td>設定ファイルの読み込みまたは保存の失敗</td></tr><tr><td><code>parse_error</code></td><td>スペックファイルの解析の失敗</td></tr></tbody></table><h2 id="カテゴリ" tabindex="-1">カテゴリ <a class="header-anchor" href="#カテゴリ" aria-label="Permalink to &quot;カテゴリ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>カテゴリ</th><th>ツール</th><th>説明</th></tr></thead><tbody><tr><td><strong>発見</strong></td><td><code>spec_list</code>, <code>spec_by_id</code>, <code>collection_by_spec</code>, <code>collection_by_id</code>, <code>tag_by_spec</code>, <code>tag_by_collection</code>, <code>tag_by_id</code></td><td>スペック階層をナビゲート：スペック、コレクション、タグを検索</td></tr><tr><td><strong>エンドポイント</strong></td><td><code>endpoint_by_spec</code>, <code>endpoint_by_collection</code>, <code>endpoint_by_tag</code>, <code>endpoint_by_id</code></td><td>階層の異なるレベルでエンドポイントを表示</td></tr><tr><td><strong>実行</strong></td><td><code>search</code>, <code>inspect</code>, <code>invoke</code></td><td>検索、完全な契約の検査、API の呼び出し</td></tr><tr><td><strong>ユーティリティ</strong></td><td><code>auth</code>, <code>info</code>, <code>response_outline</code>, <code>response_compress</code>, <code>response_slice</code></td><td>認証トークン、ランタイム情報、大規模レスポンス処理</td></tr><tr><td><strong>スキル</strong></td><td><a href="/mcp-tools/skills">フォーマットガイド</a></td><td>ツールレスポンスの表示方法をカスタマイズ</td></tr></tbody></table><h2 id="全リスト" tabindex="-1">全リスト <a class="header-anchor" href="#全リスト" aria-label="Permalink to &quot;全リスト&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ツール</th><th>説明</th></tr></thead><tbody><tr><td><code>spec_list</code></td><td>ワークスペース内のすべての API スペックを一覧表示</td></tr><tr><td><code>spec_by_id</code></td><td>コレクションを含む詳細なスペック情報を取得</td></tr><tr><td><code>collection_by_spec</code></td><td>スペック内のコレクションを一覧表示</td></tr><tr><td><code>collection_by_id</code></td><td>タグを含むコレクションの詳細を取得</td></tr><tr><td><code>tag_by_spec</code></td><td>スペック全体のすべてのタグを一覧表示</td></tr><tr><td><code>tag_by_collection</code></td><td>コレクション内のタグを一覧表示</td></tr><tr><td><code>tag_by_id</code></td><td>タグの詳細（ID、タイトル、メソッド数）を取得</td></tr><tr><td><code>endpoint_by_spec</code></td><td>スペック内のすべてのエンドポイントを一覧表示</td></tr><tr><td><code>endpoint_by_collection</code></td><td>コレクション内のエンドポイントを一覧表示</td></tr><tr><td><code>endpoint_by_tag</code></td><td>タグ内のエンドポイントを一覧表示</td></tr><tr><td><code>endpoint_by_id</code></td><td>クイックエンドポイント概要（メソッド、パス、概要）</td></tr><tr><td><code>search</code></td><td>全エンドポイントの全文検索</td></tr><tr><td><code>inspect</code></td><td>完全な OpenAPI 操作の詳細（パラメータ、スキーマ）</td></tr><tr><td><code>invoke</code></td><td>実際の API 呼び出しを実行</td></tr><tr><td><code>auth</code></td><td>スペックの認証トークンまたはヘッダーを取得</td></tr><tr><td><code>info</code></td><td>ランタイム情報（バージョン、スペック、設定）</td></tr><tr><td><code>response_outline</code></td><td>大規模レスポンスファイルの構造概要</td></tr><tr><td><code>response_compress</code></td><td>大規模レスポンスをインラインに収まるよう圧縮</td></tr><tr><td><code>response_slice</code></td><td>大規模レスポンスの断片を抽出</td></tr></tbody></table><h2 id="ナビゲーション階層" tabindex="-1">ナビゲーション階層 <a class="header-anchor" href="#ナビゲーション階層" aria-label="Permalink to &quot;ナビゲーション階層&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spec_list</span></span>
<span class="line"><span>  └── spec_by_id(id)</span></span>
<span class="line"><span>        └── collection_by_spec(specId)</span></span>
<span class="line"><span>              └── collection_by_id(id)</span></span>
<span class="line"><span>                    └── tag_by_collection(collectionId)</span></span>
<span class="line"><span>                          └── tag_by_id(id)</span></span>
<span class="line"><span>                                └── endpoint_by_tag(tagId)</span></span>
<span class="line"><span>                                      └── endpoint_by_id(id)</span></span>
<span class="line"><span>                                            └── inspect(endpointId)</span></span>
<span class="line"><span>                                                  └── invoke(endpointId)</span></span></code></pre></div><p>ID がない場合は <code>search</code> を使用してクエリでエンドポイントを検索します。<code>invoke</code> が <code>fileRef</code> を返した場合（レスポンスが大きすぎる場合）、<code>response_outline</code> → <code>response_compress</code> または <code>response_slice</code> を使用してデータを探索します。</p>`,18)])])}const b=d(a,[["render",n]]);export{h as __pageData,b as default};
